/**
 * @method
 * @name scwin.reNames
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.reNames = function () {
    /* sdd-asis-lifecycle:begin reNames — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $.each($("input:file"), function(i) {
            $(this).attr("name", "attachFiles[" + i + "]");
            $(this).attr("onchange", "fn_getFileNm(" + i + ");");
    });
    $.each($("#SendForm").find("input[name*=attach_file_nm]"), function(i) {
            $(this).attr("name", "attach_file_nm[" + i + "]");
            $(this).find("input:radio").attr("name", "attach_chk" + i);
            $(this).find("input:radio").attr("onclick", "fn_setAttach_chk(" + i + ", this.value)");
    });
    let tmp = 0;
    $.each($("#tbl_file tr"), function(i) {
            if ($(this).find("input:radio").length > 0) {
                $(this).find("input:radio").attr("name", "attach_chk" + tmp);
                $(this).find("input:radio").attr("onclick", "fn_setAttach_chk(" + tmp + ", this.value)");
                tmp = tmp + 1;
            }
    });
    /* sdd-asis-lifecycle:end */
};


